BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷114·世宗本纪一·显德元年三月亲征", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/073fb28ff5792b333432fe68e474ebdcc4b7db18/content/books/zizhi-tongjian/vol-291/year-0954/part-02/sources/library/jiuwudaishi-114-campaign-march-954/source.txt", "note": "《旧五代史》卷114·世宗本纪一·显德元年三月亲征，段落 jiu-wudaishi-205deb4a7860-p002707；已核上下文及传主，纸本及异文待核。", "id": "a16cc231-7682-57f7-9978-41bf21405923"}, {"title": "旧五代史·卷114·世宗本纪一·显德元年二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/073fb28ff5792b333432fe68e474ebdcc4b7db18/content/books/zizhi-tongjian/vol-291/year-0954/part-02/sources/library/jiuwudaishi-114-february-954/source.txt", "note": "《旧五代史》卷114·世宗本纪一·显德元年二月，段落 jiu-wudaishi-205deb4a7860-p002705；已核上下文及传主，纸本及异文待核。", "id": "10dae21b-4f3c-5e84-a715-a4a396c871f8"}, {"title": "旧五代史·卷114·世宗本纪一·显德元年三月出军诏", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/073fb28ff5792b333432fe68e474ebdcc4b7db18/content/books/zizhi-tongjian/vol-291/year-0954/part-02/sources/library/jiuwudaishi-114-march-orders-954/source.txt", "note": "《旧五代史》卷114·世宗本纪一·显德元年三月出军诏，段落 jiu-wudaishi-205deb4a7860-p002706；已核上下文及传主，纸本及异文待核。", "id": "21af9678-5c9e-5414-afad-902b05c18ba3"}, {"title": "宋史·卷488·外国四·交阯吴氏继位", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/073fb28ff5792b333432fe68e474ebdcc4b7db18/content/books/zizhi-tongjian/vol-291/year-0954/part-02/sources/library/songshi-488-changji-changwen/source.txt", "note": "《宋史》卷488·外国四·交阯吴氏继位，段落 songshi-9c6e46fee832-p075651；已核上下文及传主，纸本及异文待核。", "id": "ac9b0fa5-85ed-5b02-bc71-eff0409ca69f"}, {"title": "资治通鉴·卷291·显德元年正月至三月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/073fb28ff5792b333432fe68e474ebdcc4b7db18/content/books/zizhi-tongjian/vol-291/year-0954/part-02/sources/library/tongjian-291-954-february-march/source.txt", "note": "《资治通鉴》卷291·显德元年正月至三月，段落 zizhi-tongjian-a63549944a71-p003460；已核上下文及传主，纸本及异文待核。", "id": "5be194a3-7d40-556a-895c-33751222242a"}, {"title": "新五代史·卷64·后蜀世家第四·安思谦与王藻", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/073fb28ff5792b333432fe68e474ebdcc4b7db18/content/books/zizhi-tongjian/vol-291/year-0954/part-02/sources/library/xinwudaishi-64-ansiqian-killed/source.txt", "note": "《新五代史》卷64·后蜀世家第四·安思谦与王藻，段落 xin-wudaishi-b08f244b9241-p003240；已核上下文及传主，纸本及异文待核。", "id": "e25b5826-8b8f-522f-8fb1-1ced6298e201"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "吴权", "aliases": ["吳權"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨廷艺的旧将。938年从爱州起兵进攻皎公羡，取得交州，并在白藤江利用铁桩和潮汐击败南汉水军。生卒年本段未载。", "biography": null, "status": "draft", "id": "3d05f882-133e-5354-aa3c-d0e620ffc0ff"}, {"name": "吴昌岌", "aliases": ["吳昌岌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "静海吴氏君主，吴权之子，吴昌文之兄。《通鉴》回述其继吴权之后去世，具体死亡年此段未载。《宋史》同记其弟昌文继位，但前任链条不同，保留各书记述。", "biography": null, "status": "draft", "id": "5d6f62c8-68ad-5881-a604-6c93a84acbb4"}, {"name": "吴昌文", "aliases": ["吳昌文"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴昌岌之弟。《通鉴》回述兄死后其继位，954年正月向南汉请命，获任静海节度使兼安南都护。具体生卒年未定，继位前事不强填954年。", "biography": null, "status": "draft", "id": "aabec1ae-c866-5216-b8ee-129449b65839"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙", "刘晟", "劉晟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "杨衮", "aliases": ["楊袞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。947年麻答派他率契丹及幽州兵援杜重威；他出兵后，恒州留守军减少，为当地起兵提供时机。生卒年未载。", "biography": null, "status": "draft", "id": "4115ee92-89ee-534e-a312-a3e1bd4793d6"}, {"name": "白从晖", "aliases": ["白從暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：白从晖。", "biography": null, "status": "draft", "id": "26c4d10c-35dd-51b7-abd1-cad542bc7fe1"}, {"name": "张元徽", "aliases": ["張元徽"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武安人，刘崇的裨将。951年北汉建立时任马步军都指挥使。生卒年未载。", "biography": null, "status": "draft", "id": "b1a0aed5-927c-5e60-95b8-aea2894d7ad1"}, {"name": "安思谦", "aliases": ["安思謙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安思谦，茶酒库使、曾事藩邸者。", "biography": null, "status": "draft", "id": "6ec752d6-91f9-5760-8ea8-c552e6369345"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "安扆", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 954, "description": "后蜀将安思谦之子。史书称其与两兄弟倚父势暴横，954年与父一同被孟昶杀死。生年未载。", "biography": null, "status": "draft", "id": "0e88bd84-2d72-5b23-b92c-3644ac510cb9"}, {"name": "安嗣", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 954, "description": "后蜀将安思谦之子。史书称其与两兄弟倚父势暴横，954年与父一同被孟昶杀死。生年未载。", "biography": null, "status": "draft", "id": "1158c59d-fba8-510c-9c54-d7056d769801"}, {"name": "安裔", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 954, "description": "后蜀将安思谦之子。史书称其与两兄弟倚父势暴横，954年与父一同被孟昶杀死。生年未载。", "biography": null, "status": "draft", "id": "d486be6f-c140-517b-86fb-198cf3c31e35"}, {"name": "王藻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 954, "description": "后蜀翰林使。多次向孟昶指称安思谦怨望、将反，后因擅启边奏于954年被杀。《新五代史》补其延误边奏的叙述，生年未载。", "biography": null, "status": "draft", "id": "a610ba31-3754-557d-bb3e-f54a69d994c2"}, {"name": "李筠（原名李荣）", "aliases": ["李榮（控鶴指揮使）", "李荣（控鹤指挥使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州太原人，初名荣，后来因避周世宗讳改名筠。947年任控鹤指挥使，与何福进筹划恒州起兵，先夺甲库并组织官兵与居民作战。与李昪的父亲李荣、晚唐同名李筠分别建档。生卒年尚未录入。", "biography": null, "status": "draft", "id": "5fa92315-29cb-56c6-9108-8f703de9861a"}, {"name": "穆令均", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 954, "description": "昭义节度使李筠所属将领。954年率二千步骑迎战北汉军，被张元徽诱入伏击后杀死。生年未载。", "biography": null, "status": "draft", "id": "d39bae84-06ed-5aa2-8a07-08133e0207fb"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "王溥（后周宋初）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "949年为秘书郎，在河中平定后劝郭威焚毁涉及朝臣、藩镇的往来书信，《宋史》王溥传也记此事。与901年条所载同名王溥分开建档。生卒年留待具体原文补录。", "biography": null, "status": "draft", "id": "13d3b7ec-869a-5019-ac41-39e5abcd2df3"}, {"name": "孙汉韶", "aliases": ["孫漢韶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：孙汉韶，武定节度使、合兵奏者。", "biography": null, "status": "draft", "id": "5e4dd4c6-73f4-51a3-a55b-930f6b95eac2"}, {"name": "李廷珪", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀将领。947年十二月任奉銮肃卫都虞候，率二万兵出子午谷援长安。生卒年尚未录入。", "biography": null, "status": "draft", "id": "376820ae-41ca-57e0-b117-00976a8545fc"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "郭崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周侍卫马军都指挥使。952年郭威亲征兖州时，充在京都巡检。生卒年尚未录入。", "biography": null, "status": "draft", "id": "da797339-8eeb-5a3d-aa29-97f251a5943c"}, {"name": "王彦超", "aliases": ["王彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "临清人，后晋护圣指挥使。946年六月受命与白延遇带所属十营兵赴邢州。生卒年未载。", "biography": null, "status": "draft", "id": "c981d4c7-7693-5ee8-a667-6ab1fccba981"}, {"name": "韩通", "aliases": ["韓通"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周保义军留后。954年正月正式任保义节度使，《旧五代史》以陕州留后称其前职。生卒年暂未核定。", "biography": null, "status": "draft", "id": "81e4d74c-3057-59e4-a9a3-5baa18bff059"}, {"name": "樊爱能", "aliases": ["樊愛能"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周马军将领。954年正月获领武定节度使，旧纪同时记其军职与洋州节度职衔。生卒年暂未核定。", "biography": null, "status": "draft", "id": "31b12a36-803d-574a-a818-05742d936537"}, {"name": "何徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周虎捷指挥使。951年与王万敢、史彦超共同抵御北汉、契丹对晋州的进攻。生卒年未载。", "biography": null, "status": "draft", "id": "2982109b-18cc-561f-9927-a98ba7b7f5e6"}, {"name": "白重赞", "aliases": ["白重贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周武成节度使。953年九月己亥奏报已堵塞决口的黄河。生卒年未载。", "biography": null, "status": "draft", "id": "b6889cb5-a3c4-5b6a-aa6e-7feda1afc895"}, {"name": "史彦超（后周将领）", "aliases": ["史彦超", "史彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "云州人，后周龙捷都指挥使。951年与王万敢、何徽防守晋州，抵抗北汉、契丹军。尚不与其他政权的同名将领合并，生卒年未录全。", "biography": null, "status": "draft", "id": "541b4701-1443-5a49-a822-4dc8d508ecee"}, {"name": "符彦能", "aliases": ["符彥能"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "前耀州团练使。954年三月随樊爱能、何徽等受命先赴泽州，为迎击北汉的军队成员。生卒年未载。", "biography": null, "status": "draft", "id": "4e1712fd-4caf-5fc8-aa42-931818d8a80f"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}, {"name": "郑仁诲", "aliases": ["鄭仁誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，后周内客省使、恩州团练使。952年三月任枢密副使，新旧五代史同日记载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "f7eb66ac-1c5c-5720-aa2e-9256e75c2b71"}, {"name": "赵晁", "aliases": ["趙晁"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "真定人，后周控鹤都指挥使。954年三月向郑好谦表示宜慎重进军，郑转告柴荣后，两人被拘于怀州狱。生卒年未载。", "biography": null, "status": "draft", "id": "cd9622d4-b011-5634-b050-b6b748a36838"}, {"name": "郑好谦", "aliases": ["鄭好謙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周通事舍人。951年奉郭威之命前往安抚慕容彦超，并与其盟誓。生卒年未载。", "biography": null, "status": "draft", "id": "0b4ce788-095c-5411-b480-a87a1b41c0ae"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
